int vmw_overlay_pause_all ( struct vmw_private * dev_priv ) { struct vmw_overlay * overlay = dev_priv -> overlay_priv ; int i , ret ; mutex_lock ( & overlay -> mutex ) ; for ( i = 0 ; i < VMW_MAX_NUM_STREAMS ; i ++ ) { if ( overlay -> stream [ i ] . paused ) { DRM_INFO ( "%s: *warning* stream %i already paused\n" , __func__ , i ) ; } ret = vmw_overlay_stop ( dev_priv , i , true , false ) ; WARN_ON ( ret != 0 ) ; } mutex_unlock ( & overlay -> mutex ) ; return 0 ; } 